import typing

import tenacity


def my_stop(retry_state: tenacity.RetryCallState) -> bool:
    return True


def my_retry(retry_state: tenacity.RetryCallState) -> bool:
    return False


def my_wait(retry_state: tenacity.RetryCallState) -> bool:
    return False


def test_retrying_accepts_callable_callbacks() -> None:
    r = tenacity.Retrying(retry=my_retry, wait=my_wait, stop=my_stop)
    assert r.retry is my_retry
    assert r.wait is my_wait
    assert r.stop is my_stop
    assert typing.get_type_hints(r.__init__) is not None
    assert typing.get_type_hints(r.copy) is not None


def test_retrying_with_callable_callbacks_runs() -> None:
    calls: list[int] = []

    def stop_after_one(retry_state: tenacity.RetryCallState) -> bool:
        return retry_state.attempt_number >= 2

    def wait_zero(retry_state: tenacity.RetryCallState) -> bool:
        return 0.0

    def retry_if_result_odd(retry_state: tenacity.RetryCallState) -> bool:
        if retry_state.outcome is not None and not retry_state.outcome.failed:
            return retry_state.outcome.result() % 2 == 1
        return True

    for attempt in tenacity.Retrying(
        stop=stop_after_one, wait=wait_zero, retry=retry_if_result_odd
    ):
        with attempt:
            calls.append(len(calls))
            raise tenacity.TryAgain()
    assert len(calls) == 2

