import ipaddress

import pytest

from marshmallow import Schema


class TestIPTypeMappings:
    @pytest.mark.parametrize(
        "py_type, field_cls",
        [
            (ipaddress.IPv4Address, "IPv4"),
            (ipaddress.IPv6Address, "IPv6"),
            (ipaddress.IPv4Interface, "IPv4Interface"),
            (ipaddress.IPv6Interface, "IPv6Interface"),
        ],
    )
    def test_type_mapping_present(self, py_type, field_cls):
        from marshmallow import fields

        assert py_type in Schema.TYPE_MAPPING
        assert Schema.TYPE_MAPPING[py_type] is getattr(fields, field_cls)

    def test_ipv4_address_roundtrip(self):
        from marshmallow import fields

        class IPSchema(Schema):
            addr = fields.IPv4()

        schema = IPSchema()
        obj = {"addr": ipaddress.IPv4Address("192.0.2.1")}
        dumped = schema.dump(obj)
        assert dumped == {"addr": "192.0.2.1"}
        loaded = schema.load(dumped)
        assert loaded == {"addr": ipaddress.IPv4Address("192.0.2.1")}

    def test_ipv6_address_roundtrip(self):
        from marshmallow import fields

        class IPSchema(Schema):
            addr = fields.IPv6()

        schema = IPSchema()
        obj = {"addr": ipaddress.IPv6Address("::1")}
        dumped = schema.dump(obj)
        assert dumped == {"addr": "::1"}
        loaded = schema.load(dumped)
        assert loaded == {"addr": ipaddress.IPv6Address("::1")}

    def test_ipv4_interface_roundtrip(self):
        from marshmallow import fields

        class IPSchema(Schema):
            iface = fields.IPv4Interface()

        schema = IPSchema()
        obj = {"iface": ipaddress.IPv4Interface("192.0.2.1/24")}
        dumped = schema.dump(obj)
        assert dumped == {"iface": "192.0.2.1/24"}
        loaded = schema.load(dumped)
        assert loaded == {"iface": ipaddress.IPv4Interface("192.0.2.1/24")}

    def test_ipv6_interface_roundtrip(self):
        from marshmallow import fields

        class IPSchema(Schema):
            iface = fields.IPv6Interface()

        schema = IPSchema()
        obj = {"iface": ipaddress.IPv6Interface("::1/64")}
        dumped = schema.dump(obj)
        assert dumped == {"iface": "::1/64"}
        loaded = schema.load(dumped)
        assert loaded == {"iface": ipaddress.IPv6Interface("::1/64")}

