import click
from click.testing import CliRunner


def test_invoke_mix_stderr_removed():
    """CliRunner.invoke should not accept mix_stderr parameter."""
    @click.command()
    def cli():
        click.echo('out')
        click.echo('err', err=True)

    runner = CliRunner()
    try:
        result = runner.invoke(cli, mix_stderr=False)
    except TypeError as e:
        assert 'mix_stderr' in str(e)
    else:
        raise AssertionError('Expected TypeError for mix_stderr parameter')

    # Ensure normal invocation still works and stderr is mixed by default.
    result = runner.invoke(cli)
    assert result.exit_code == 0
    assert result.output == 'out\nerr\n'
    assert result.stdout == 'out\nerr\n'
    try:
        result.stderr
    except ValueError:
        pass
    else:
        raise AssertionError('stderr should not be separately captured by default')

