    """ProgressBar instance attributes should have type annotations."""
    bar = click.progressbar(range(10))
    assert isinstance(bar.label, str)
    assert isinstance(bar.width, int)
    assert isinstance(bar.autowidth, bool)
    assert isinstance(bar.eta_known, bool)
    assert isinstance(bar.finished, bool)
    assert isinstance(bar.entered, bool)
    assert isinstance(bar.is_hidden, bool)

