@pytest.mark.skipif(
    sys.version_info < (3, 8),
    reason="requires typing_extensions or Python 3.8+",
)
def test_errorhandler_type_check() -> None:
    """Test that errorhandler decorator accepts callables with
    parameter type that is a supertype of the exception type."""
    from flask import Flask
    from flask.typing import ResponseReturnValue

    app = Flask(__name__)

    # This should type-check without error.
    @app.errorhandler(Exception)
    def handle_any_exception(e: Exception) -> ResponseReturnValue:
        return "generic error", 500

    # This should also type-check.
    @app.errorhandler(ValueError)
    def handle_value_error(e: Exception) -> ResponseReturnValue:
        return "value error", 500

    # This should fail type-checking because handler parameter is
    # narrower than the exception type.
    with pytest.raises(TypeError):
        @app.errorhandler(Exception)
        def handle_bad(e: ValueError) -> ResponseReturnValue:
            return "bad", 500

    # This should fail type-checking because exception types are unrelated.
    with pytest.raises(TypeError):
        @app.errorhandler(KeyError)
        def handler_value_error(e: ValueError) -> ResponseReturnValue:
            return "value error", 500

    # This should type-check without error.
    @app.errorhandler(404)
    def handle_404(error: Exception) -> ResponseReturnValue:
        return "not found", 404

